using System;using System.Collections;using System.Reflection;using UnityEngine;
public sealed class BicycleReturnTests:MonoBehaviour
{
 public static bool UseAI;static bool booted;public static bool ReadKey(KeyCode k){return false;}public static bool ReadDown(KeyCode k){return false;}const BindingFlags SP=BindingFlags.Static|BindingFlags.NonPublic,IP=BindingFlags.Instance|BindingFlags.NonPublic;Type pt;Component fan,zhao,manager;Rigidbody2D ball;float floor,scale;int checks,failures;
 public static void Boot(){if(booted)return;booted=true;ControlBindings.settingsPath=System.IO.Path.Combine(Application.dataPath,"..","bicycle-return-test.ini");var o=new GameObject("BicycleReturnTests");DontDestroyOnLoad(o);o.AddComponent<BicycleReturnTests>();}
 void Check(bool ok,string text){checks++;if(!ok)failures++;Debug.Log("ABILITY "+(ok?"PASS ":"FAIL ")+text);}
 Rigidbody2D Body(Component a){return (Rigidbody2D)pt.GetField("rb").GetValue(a);}void Move(Component a,Vector2 at){a.transform.position+=(Vector3)(at-Body(a).position);foreach(var b in a.GetComponentsInChildren<Rigidbody2D>()){b.velocity=Vector2.zero;b.angularVelocity=0;}Physics2D.SyncTransforms();}
 object Get(Component a,string n){return typeof(SkillRework).GetField(n,IP).GetValue(a.GetComponent<SkillRework>());}void Set(Component a,string n,object value){typeof(SkillRework).GetField(n,IP).SetValue(a.GetComponent<SkillRework>(),value);}bool Upright(Component a){return (bool)typeof(SkillRework).GetMethod("UprightSupported",IP).Invoke(a.GetComponent<SkillRework>(),null);}void Restore(Component a){typeof(SkillRework).GetMethod("RestoreFacing",IP).Invoke(a.GetComponent<SkillRework>(),new object[]{false});}
 void Freeze(Component a){foreach(var rb in a.GetComponentsInChildren<Rigidbody2D>())rb.constraints=RigidbodyConstraints2D.FreezeAll;}IEnumerator Ticks(int n){for(int i=0;i<n;i++)yield return new WaitForFixedUpdate();}
 IEnumerator Scene(int mode,bool side=true){UseAI=false;Time.timeScale=1;AbilityMode.SetBudget(24);SkillGroups.Reset(mode==1);PlayerSkills.Enabled=mode==1;AbilityMode.Enabled=mode==2;if(mode==1){SkillGroups.Set(0,side?0:1);SkillGroups.Set(1,side?1:0);}else{AbilityMode.Reset();AbilityMode.Builds[side?0:1].Purchased=(1<<10)|(1<<11);}
  typeof(GameAIMod).GetMethod("BeginGame",SP).Invoke(null,new object[]{0});yield return new WaitForSeconds(.55f);pt=Type.GetType("PlayerController, Assembly-CSharp");fan=GameObject.Find("Fan").GetComponent(pt);zhao=GameObject.Find("Zhao").GetComponent(pt);manager=FindObjectOfType(pt.Assembly.GetType("GameManager")) as Component;ball=(FindObjectOfType(pt.Assembly.GetType("Ball")) as Component).GetComponent<Rigidbody2D>();floor=GameObject.Find("Down").GetComponent<Collider2D>().bounds.max.y;scale=Mathf.Abs(fan.transform.lossyScale.x)/.8f;ball.position=new Vector2(0,5);ball.velocity=Vector2.zero;ball.gravityScale=0;GameAIMod.OnBallReset();yield return Ticks(3);
 }
 void Seed(){for(int n=0;n<100;n++){UnityEngine.Random.InitState(n);if(UnityEngine.Random.value<.5f){UnityEngine.Random.InitState(n);return;}}}
 IEnumerator Motion(bool side,int mode){yield return Scene(mode,side);var a=side?fan:zhao;float dir=side?1:-1;Move(a,new Vector2(0,Body(a).position.y));Move(side?zhao:fan,new Vector2(-dir*5,Body(side?zhao:fan).position.y));ball.position=Body(a).position+new Vector2(-dir*.58f*scale,1.2f*scale);ball.velocity=Vector2.zero;ball.gravityScale=0;Physics2D.SyncTransforms();Seed();yield return Ticks(2);bool started=SkillRework.Mirrored(a),back=false,gotup=false,early=false,released=false;float uprightAt=-1,releasedAt=-1,began=Time.time;
  for(int i=0;i<380;i++){yield return new WaitForFixedUpdate();back|=(float)Get(a,"landedAt")>=0;gotup|=(float)Get(a,"getupAt")>=0;if(SkillRework.Mirrored(a)&&!back&&!SkillRework.InBicycle(a))early=true;if(gotup&&Upright(a)&&uprightAt<0)uprightAt=Time.time;if(!SkillRework.Mirrored(a)){released=true;releasedAt=Time.time;break;}}
  Check(started&&back&&gotup&&released&&!early,"actual bicycle keeps back landing/getup and restores facing actor="+a.name+" mode="+mode+" started="+started+" back="+back+" up="+gotup+" released="+released);
  Check(released&&!SkillRework.InBicycle(a)&&(bool)Get(a,"poseOwned")==false&&(uprightAt<0||releasedAt-uprightAt<=Time.fixedDeltaTime*2.1f),"actual upright recovery immediately releases pose and AI action lock actor="+a.name+" duration="+(releasedAt-began));
 }
 IEnumerator Residual(bool side){yield return Scene(2,side);var a=side?fan:zhao;var o=side?zhao:fan;float dir=side?1:-1;Move(a,new Vector2(0,Body(a).position.y));Move(o,new Vector2(-dir*5,Body(o).position.y));yield return Ticks(25);SkillRework.ApplyMirror(a,true);Set(a,"getupAt",Time.time-.6f);Set(a,"landedAt",Time.time-.7f);Set(a,"bicycleUntil",Time.time+3f);Set(a,"observedSpin",1000f);float now=Time.time;bool supported=Upright(a);Vector2 before=Body(a).position;Restore(a);Check(supported&&!SkillRework.Mirrored(a)&&!SkillRework.InBicycle(a)&&Time.time==now&&Vector2.Distance(before,Body(a).position)<.001f,"standing turns immediately despite residual spin and unexpired action timer actor="+a.name);
  // Both controllers resume normal AI decisions; no single-player AI substitute.
  ball.position=new Vector2(dir*3f,floor+ball.GetComponent<Collider2D>().bounds.extents.y+.01f);ball.gravityScale=1;ball.velocity=Vector2.zero;UseAI=true;GameAIMod.GetAxis("Horizontal",fan);GameAIMod.GetAxis("Horizontal2",zhao);var states=(System.Collections.IDictionary)typeof(GameAIMod).GetField("states",SP).GetValue(null);foreach(var value in states.Values){var t=value.GetType();t.GetField("serveApproach",BindingFlags.Public|BindingFlags.Instance).SetValue(value,false);t.GetField("waitingForServe",BindingFlags.Public|BindingFlags.Instance).SetValue(value,false);t.GetField("frame",BindingFlags.Public|BindingFlags.Instance).SetValue(value,-1);}float startX=Body(a).position.x;bool reacted=false;for(int i=0;i<35;i++){yield return new WaitForFixedUpdate();float axis=GameAIMod.GetAxis(side?"Horizontal":"Horizontal2",a);reacted|=axis*dir>.1f;}UseAI=false;Check(reacted&&dir*(Body(a).position.x-startX)>.08f,"both AIs active: recovered player resumes pursuit without long idle actor="+a.name+" moved="+(Body(a).position.x-startX));
 }
 Collider2D Frame(Component a){var goal=(Collider2D)Get(a,"goal");Collider2D best=null;foreach(var c in goal.transform.parent.GetComponentsInChildren<Collider2D>())if(!c.isTrigger&&(best==null||c.bounds.center.y>best.bounds.center.y))best=c;return best;}
 IEnumerator Post(bool side,int mode){yield return Scene(mode,side);var a=side?fan:zhao;var other=side?zhao:fan;float dir=side?1:-1;if(mode==2)AbilityMode.For(a).Purchased=(1<<1)|(1<<11);Freeze(a);Freeze(other);var bar=Frame(a);var goal=(Collider2D)Get(a,"goal");foreach(var c in goal.transform.parent.GetComponentsInChildren<Collider2D>())if(!c.isTrigger)Debug.Log("POST_SHAPE "+c.name+" "+c.bounds);float x=dir>0?goal.bounds.min.x:goal.bounds.max.x;Move(a,new Vector2(x-dir*1.7f,Body(a).position.y));var head=a.transform.Find("Head").GetComponent<Collider2D>();float r=ball.GetComponent<Collider2D>().bounds.extents.y;float desired=BallBoundaryGuard.FindGoalCeiling(goal)+r*.5f;Move(a,Body(a).position+Vector2.up*(desired-(head.bounds.max.y+r-.01f*scale)));Move(other,new Vector2(-dir*5,Body(other).position.y));ball.position=new Vector2(head.bounds.center.x,head.bounds.max.y+r-.01f*scale);ball.velocity=Vector2.down*.5f;ball.gravityScale=0;var probe=ball.gameObject.AddComponent<PostImpactProbe>();probe.root=goal.transform.parent;Physics2D.SyncTransforms();PlayerSkills.SetAction((Animator)pt.GetField("anim").GetValue(a),"Head",a);for(int i=0;i<90&&SkillRework.ResilienceStacks(a)==0;i++)yield return new WaitForFixedUpdate();Check(probe.hits>0&&SkillRework.ResilienceStacks(a)==1,"real launched header hits opposing goal frame and earns resilience actor="+a.name+" mode="+mode+" hits="+probe.hits+" stacks="+SkillRework.ResilienceStacks(a)+" ball="+ball.position);
  Check(SkillRework.ShootingLevel(a)==5.5f,"post rebound grants exactly +1.5 shooting actor="+a.name);var body=Body(other).GetComponent<Collider2D>();ball.position=body.ClosestPoint((Vector2)body.bounds.center+Vector2.right*dir*3)+Vector2.right*dir*(r-.005f);ball.velocity=Vector2.right*-dir*2;Physics2D.SyncTransforms();yield return Ticks(8);Check(SkillRework.ResilienceStacks(a)==1,"same shot rebounding into defender is not counted again actor="+a.name);
 }
 IEnumerator Unshot(){yield return Scene(2);Freeze(fan);Freeze(zhao);Move(fan,new Vector2(-5,Body(fan).position.y));var bar=Frame(fan);var goal=(Collider2D)Get(fan,"goal");var probe=ball.gameObject.AddComponent<PostImpactProbe>();probe.root=goal.transform.parent;float radius=ball.GetComponent<Collider2D>().bounds.extents.x;ball.position=new Vector2(bar.bounds.min.x-radius-.15f,bar.bounds.center.y);ball.velocity=Vector2.right*8;ball.gravityScale=0;Physics2D.SyncTransforms();yield return Ticks(15);Check(probe.hits>0&&SkillRework.ResilienceStacks(fan)==0,"unshot ball hitting frame grants no resilience");}
 IEnumerator Start(){Application.runInBackground=true;Application.targetFrameRate=120;QualitySettings.vSyncCount=0;AudioListener.volume=0;Time.captureFramerate=100;yield return new WaitForSeconds(.2f);foreach(int mode in new[]{1,2})foreach(bool side in new[]{true,false}){yield return Motion(side,mode);yield return Post(side,mode);}yield return Residual(true);yield return Residual(false);yield return Unshot();Debug.Log("ABILITY COMPLETE checks="+checks+" failures="+failures);Application.Quit(failures==0?0:1);}
 void Update(){if(Time.realtimeSinceStartup>145f){Debug.LogError("ABILITY TIMEOUT");Application.Quit(2);}}
}
public sealed class PostImpactProbe:MonoBehaviour{public Transform root;public int hits;void OnCollisionEnter2D(Collision2D c){if(c.collider!=null&&!c.collider.isTrigger&&root!=null&&c.collider.transform.IsChildOf(root))hits++;}}
